Here is a complete, production-ready, and highly robust Order Processing and Inventory Management System implemented in C#. 

The system is structured into three decoupled layers:
1. **RESTful API Endpoint Router & Controller**: Handles, validates, and routes incoming purchase orders asynchronously.
2. **Inventory Reservation Engine**: Prevents race conditions during high-concurrency stock depletion using a custom, **Ref-Counted Key-Level Lock Manager** and deterministic sorting to guarantee deadlock avoidance.
3. **Payment Gateway Integration Subsystem**: Implements a highly resilient, thread-safe, custom **State-Machine Circuit Breaker Pattern** to handle transient faults and timeouts elegantly without external dependencies.

---

### Project Architecture & Source Code

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Net;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace EnterpriseOrderSystem
{
    #region COMMON MODELS & INTERFACES

    public record OrderItemDto(
        [Required] string ProductId, 
        [Range(1, 1000, ErrorMessage = "Quantity must be between 1 and 1000.")] int Quantity
    );

    public record PurchaseOrderRequest(
        [Required] string CustomerId, 
        [Required] List<OrderItemDto> Items
    );

    public record OrderResponse(
        string OrderId, 
        string Status, 
        decimal TotalPrice, 
        string? ErrorDetails = null
    );

    public class InventoryItem
    {
        public string ProductId { get; init; } = string.Empty;
        public string Sku { get; init; } = string.Empty;
        public int AvailableStock { get; set; }
        public decimal UnitPrice { get; init; }
    }

    public enum CircuitState
    {
        Closed,
        Open,
        HalfOpen
    }

    #endregion

    #region LAYER 2: CONCURRENCY & INVENTORY RESERVATION ENGINE

    /// <summary>
    /// Provides production-grade, thread-safe, key-level locking.
    /// This prevents global bottlenecks by only locking specific product IDs being updated,
    /// and uses reference counting to safely clean up unused semaphores from memory.
    /// </summary>
    public class KeyLevelLockManager
    {
        private class RefCountedSemaphore
        {
            public SemaphoreSlim Semaphore { get; } = new(1, 1);
            public int RefCount { get; set; } = 1;
        }

        private readonly ConcurrentDictionary<string, RefCountedSemaphore> _semaphores = new();

        public async Task<IDisposable> AcquireLockAsync(string key, CancellationToken cancellationToken = default)
        {
            RefCountedSemaphore refCounter;
            lock (_semaphores)
            {
                refCounter = _semaphores.GetOrAdd(key, _ => new RefCountedSemaphore());
                refCounter.RefCount++;
            }

            await refCounter.Semaphore.WaitAsync(cancellationToken);
            return new Releaser(this, key);
        }

        private void Release(string key)
        {
            RefCountedSemaphore? refCounter;
            lock (_semaphores)
            {
                if (!_semaphores.TryGetValue(key, out refCounter)) return;

                refCounter.RefCount--;
                if (refCounter.RefCount <= 0)
                {
                    _semaphores.TryRemove(key, out _);
                }
            }
            refCounter.Semaphore.Release();
        }

        private sealed class Releaser : IDisposable
        {
            private readonly KeyLevelLockManager _lockManager;
            private readonly string _key;
            private int _disposed;

            public Releaser(KeyLevelLockManager lockManager, string key)
            {
                _lockManager = lockManager;
                _key = key;
            }

            public void Dispose()
            {
                if (Interlocked.CompareExchange(ref _disposed, 1, 0) == 0)
                {
                    _lockManager.Release(_key);
                }
            }
        }
    }

    public interface IInventoryReservationEngine
    {
        Task<bool> ReserveStockAsync(string orderId, List<OrderItemDto> items);
        Task ReleaseStockAsync(string orderId, List<OrderItemDto> items);
        Task<decimal> CalculateTotalAndValidateAsync(List<OrderItemDto> items);
    }

    /// <summary>
    /// Prevents race conditions during stock depletion under heavy concurrency.
    /// Implements deterministic product ID sorting to completely avoid deadlocks.
    /// </summary>
    public class InventoryReservationEngine : IInventoryReservationEngine
    {
        private readonly KeyLevelLockManager _lockManager = new();
        private readonly ConcurrentDictionary<string, InventoryItem> _databaseSimulator = new();

        public InventoryReservationEngine()
        {
            // Seed our system with mock products
            _databaseSimulator["PROD-001"] = new InventoryItem { ProductId = "PROD-001", Sku = "SKU-LAPTOP", AvailableStock = 10, UnitPrice = 999.99m };
            _databaseSimulator["PROD-002"] = new InventoryItem { ProductId = "PROD-002", Sku = "SKU-MOUSE", AvailableStock = 5, UnitPrice = 49.99m };
            _databaseSimulator["PROD-003"] = new InventoryItem { ProductId = "PROD-003", Sku = "SKU-MONITOR", AvailableStock = 2, UnitPrice = 299.99m };
        }

        public async Task<decimal> CalculateTotalAndValidateAsync(List<OrderItemDto> items)
        {
            decimal total = 0;
            foreach (var item in items)
            {
                if (!_databaseSimulator.TryGetValue(item.ProductId, out var invItem))
                {
                    throw new KeyNotFoundException($"Product '{item.ProductId}' does not exist.");
                }
                total += invItem.UnitPrice * item.Quantity;
            }
            return await Task.FromResult(total);
        }

        public async Task<bool> ReserveStockAsync(string orderId, List<OrderItemDto> items)
        {
            // Crucial: Deterministically sort the product IDs to enforce a strict locking hierarchy.
            // This guarantees deadlock prevention during concurrent operations requesting the same resources.
            var sortedItems = items.OrderBy(i => i.ProductId).ToList();
            var acquiredLocks = new List<IDisposable>();

            try
            {
                // Step 1: Acquire fine-grained locks sequentially based on sorted order
                foreach (var item in sortedItems)
                {
                    var productLock = await _lockManager.AcquireLockAsync(item.ProductId);
                    acquiredLocks.Add(productLock);
                }

                // Step 2: Validate available inventory levels for ALL requested products
                foreach (var item in sortedItems)
                {
                    if (!_databaseSimulator.TryGetValue(item.ProductId, out var stockItem))
                    {
                        return false; // Product not found
                    }

                    if (stockItem.AvailableStock < item.Quantity)
                    {
                        return false; // Insufficient Stock
                    }
                }

                // Step 3: Transactionally deplete resources
                foreach (var item in sortedItems)
                {
                    var stockItem = _databaseSimulator[item.ProductId];
                    stockItem.AvailableStock -= item.Quantity;
                    Console.WriteLine($"[INVENTORY] Reserved {item.Quantity} units of {item.ProductId}. Stock remaining: {stockItem.AvailableStock}");
                }

                return true;
            }
            finally
            {
                // Step 4: Always release locks in reverse order to unwind gracefully
                for (int i = acquiredLocks.Count - 1; i >= 0; i--)
                {
                    acquiredLocks[i].Dispose();
                }
            }
        }

        public async Task ReleaseStockAsync(string orderId, List<OrderItemDto> items)
        {
            // Deterministic sort for safe rollback execution
            var sortedItems = items.OrderBy(i => i.ProductId).ToList();
            var acquiredLocks = new List<IDisposable>();

            try
            {
                foreach (var item in sortedItems)
                {
                    var productLock = await _lockManager.AcquireLockAsync(item.ProductId);
                    acquiredLocks.Add(productLock);
                }

                foreach (var item in sortedItems)
                {
                    if (_databaseSimulator.TryGetValue(item.ProductId, out var stockItem))
                    {
                        stockItem.AvailableStock += item.Quantity;
                        Console.WriteLine($"[INVENTORY ROLLBACK] Released {item.Quantity} units of {item.ProductId}. Stock restored: {stockItem.AvailableStock}");
                    }
                }
            }
            finally
            {
                for (int i = acquiredLocks.Count - 1; i >= 0; i--)
                {
                    acquiredLocks[i].Dispose();
                }
            }
        }
    }

    #endregion

    #region LAYER 3: PAYMENT GATEWAY SUB-SYSTEM & CIRCUIT BREAKER

    public class CircuitBreakerOpenException : Exception
    {
        public CircuitBreakerOpenException(string message) : base(message) { }
    }

    /// <summary>
    /// Thread-safe Circuit Breaker implementing the Closed, Open, and Half-Open lifecycle state transitions.
    /// Handles third-party system degradation and failure modes cleanly.
    /// </summary>
    public class CustomCircuitBreaker
    {
        private readonly object _lock = new();
        private readonly int _failureThreshold;
        private readonly TimeSpan _breakDuration;

        private CircuitState _state = CircuitState.Closed;
        private int _consecutiveFailures;
        private DateTime _nextAttemptAllowedTime = DateTime.MinValue;

        public CircuitState State
        {
            get
            {
                lock (_lock)
                {
                    EvaluateStateTransition();
                    return _state;
                }
            }
        }

        public CustomCircuitBreaker(int failureThreshold = 3, TimeSpan? breakDuration = null)
        {
            _failureThreshold = failureThreshold;
            _breakDuration = breakDuration ?? TimeSpan.FromSeconds(5);
        }

        public async Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken cancellationToken = default)
        {
            lock (_lock)
            {
                EvaluateStateTransition();

                if (_state == CircuitState.Open)
                {
                    throw new CircuitBreakerOpenException($"Circuit Breaker is OPEN. Execution blocked until {_nextAttemptAllowedTime:HH:mm:ss}.");
                }

                if (_state == CircuitState.HalfOpen)
                {
                    // Restrict entry to a single probe test during Half-Open state.
                    // If multiple requests hit concurrently, fail-fast on the others to protect downstream systems.
                    _state = CircuitState.Open; // Immediately re-trip to block transient concurrent requests
                    _nextAttemptAllowedTime = DateTime.UtcNow.Add(_breakDuration); // push the window
                }
            }

            try
            {
                // Run execution through the circuit protected window
                var result = await action(cancellationToken);

                OnSuccess();
                return result;
            }
            catch (Exception)
            {
                OnFailure();
                throw;
            }
        }

        private void EvaluateStateTransition()
        {
            if (_state == CircuitState.Open && DateTime.UtcNow >= _nextAttemptAllowedTime)
            {
                _state = CircuitState.HalfOpen;
                Console.WriteLine("[CIRCUIT BREAKER] Circuit transitioned to HALF-OPEN. Running integration health probes...");
            }
        }

        private void OnSuccess()
        {
            lock (_lock)
            {
                if (_state == CircuitState.HalfOpen || _consecutiveFailures > 0)
                {
                    Console.WriteLine("[CIRCUIT BREAKER] Remote call succeeded. Resetting Circuit to CLOSED.");
                }
                _state = CircuitState.Closed;
                _consecutiveFailures = 0;
            }
        }

        private void OnFailure()
        {
            lock (_lock)
            {
                _consecutiveFailures++;
                Console.WriteLine($"[CIRCUIT BREAKER] Transient failure registered. Failure count: {_consecutiveFailures}/{_failureThreshold}.");

                if (_consecutiveFailures >= _failureThreshold || _state == CircuitState.HalfOpen)
                {
                    _state = CircuitState.Open;
                    _nextAttemptAllowedTime = DateTime.UtcNow.Add(_breakDuration);
                    Console.WriteLine($"[CIRCUIT BREAKER] Danger: Threshold reached. Tripping Circuit to OPEN for {_breakDuration.TotalSeconds}s.");
                }
            }
        }
    }

    public interface IPaymentGatewayService
    {
        Task<bool> ProcessPaymentAsync(string orderId, decimal amount);
    }

    /// <summary>
    /// Production resilient payment service wrapper protecting outgoing network hops
    /// </summary>
    public class PaymentGatewayService : IPaymentGatewayService
    {
        private readonly CustomCircuitBreaker _circuitBreaker;
        private readonly Random _randomGenerator = new();

        public PaymentGatewayService(CustomCircuitBreaker? circuitBreaker = null)
        {
            _circuitBreaker = circuitBreaker ?? new CustomCircuitBreaker();
        }

        public async Task<bool> ProcessPaymentAsync(string orderId, decimal amount)
        {
            return await _circuitBreaker.ExecuteAsync(async (cancellationToken) =>
            {
                using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                // Hard timeout limit of 2 seconds for payment execution
                cts.CancelAfter(TimeSpan.FromSeconds(2)); 

                try
                {
                    return await SimulateThirdPartyCallAsync(amount, cts.Token);
                }
                catch (OperationCanceledException)
                {
                    Console.WriteLine($"[PAYMENT] Latency limit breached. Gateway timeout for Order ID: {orderId}");
                    throw new TimeoutException("The payment gateway timed out responding to API requests.");
                }
            });
        }

        private async Task<bool> SimulateThirdPartyCallAsync(decimal amount, CancellationToken token)
        {
            // Simulate random latency between 100ms and 3000ms
            int delay = _randomGenerator.Next(100, 3000);
            await Task.Delay(delay, token);

            // Simulate deterministic gateway failures for extreme amounts
            if (amount > 5000.00m)
            {
                throw new InvalidOperationException("External Gateway failed. Reason: Transaction amount exceeds limits.");
            }

            return true;
        }
    }

    #endregion

    #region LAYER 1: RESTful API ENDPOINT ROUTER & COORDINATION

    public interface IOrderProcessingCoordinator
    {
        Task<OrderResponse> ProcessOrderAsync(PurchaseOrderRequest request);
    }

    /// <summary>
    /// Acts as an orchestrator orchestrating Layer 2 (Inventory) and Layer 3 (Payment Gateway).
    /// Prevents data inconsistency using custom transaction rollbacks.
    /// </summary>
    public class OrderProcessingCoordinator : IOrderProcessingCoordinator
    {
        private readonly IInventoryReservationEngine _inventoryEngine;
        private readonly IPaymentGatewayService _paymentService;

        public OrderProcessingCoordinator(IInventoryReservationEngine inventoryEngine, IPaymentGatewayService paymentService)
        {
            _inventoryEngine = inventoryEngine;
            _paymentService = paymentService;
        }

        public async Task<OrderResponse> ProcessOrderAsync(PurchaseOrderRequest request)
        {
            var orderId = Guid.NewGuid().ToString("N");
            decimal totalAmount;

            try
            {
                totalAmount = await _inventoryEngine.CalculateTotalAndValidateAsync(request.Items);
            }
            catch (KeyNotFoundException ex)
            {
                return new OrderResponse(orderId, "FAILED", 0, ex.Message);
            }

            // Phase 1: Resource Reservation
            bool isReserved = await _inventoryEngine.ReserveStockAsync(orderId, request.Items);
            if (!isReserved)
            {
                return new OrderResponse(orderId, "REJECTED_OUT_OF_STOCK", 0, "Requested quantities exceed available stock levels.");
            }

            // Phase 2: Resilient Payment Processing
            try
            {
                bool paymentSuccess = await _paymentService.ProcessPaymentAsync(orderId, totalAmount);
                if (paymentSuccess)
                {
                    return new OrderResponse(orderId, "COMPLETED", totalAmount);
                }

                throw new InvalidOperationException("Payment was declined by the network provider.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[ORCHESTRATOR ERROR] Payment failed: {ex.Message}. Rollback initiated.");

                // Compensating Transaction Strategy: Restore stock allocation atomically
                await _inventoryEngine.ReleaseStockAsync(orderId, request.Items);

                string failureReason = ex is CircuitBreakerOpenException 
                    ? "Payment service degraded. System entered protective standby mode." 
                    : $"Transaction aborted: {ex.Message}";

                return new OrderResponse(orderId, "ROLLBACK_COMPLETED", totalAmount, failureReason);
            }
        }
    }

    /// <summary>
    /// Low-overhead HTTP Routing Router mimicking ASP.NET Core Minimal API / Controller mechanisms.
    /// Safely handles exception propagation, schema validation and formats JSON string payloads.
    /// </summary>
    public class OrdersApiController
    {
        private readonly IOrderProcessingCoordinator _coordinator;

        public OrdersApiController(IOrderProcessingCoordinator coordinator)
        {
            _coordinator = coordinator;
        }

        public async Task<(HttpStatusCode StatusCode, string JsonResponse)> PostOrderAsync(string rawJsonPayload)
        {
            try
            {
                // Validate payload construction
                var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                var request = JsonSerializer.Deserialize<PurchaseOrderRequest>(rawJsonPayload, options);

                if (request == null || string.IsNullOrWhiteSpace(request.CustomerId) || request.Items == null || !request.Items.Any())
                {
                    return (HttpStatusCode.BadRequest, ToJson(new { Error = "Malformed payload validation failed. Customer ID and valid Items properties are mandatory." }));
                }

                foreach (var item in request.Items)
                {
                    if (item.Quantity <= 0 || string.IsNullOrWhiteSpace(item.ProductId))
                    {
                        return (HttpStatusCode.UnprocessableEntity, ToJson(new { Error = "Invalid line item properties. Quantity must be positive." }));
                    }
                }

                var processingResult = await _coordinator.ProcessOrderAsync(request);

                return processingResult.Status switch
                {
                    "COMPLETED" => (HttpStatusCode.Created, ToJson(processingResult)),
                    "REJECTED_OUT_OF_STOCK" => (HttpStatusCode.Conflict, ToJson(processingResult)),
                    "ROLLBACK_COMPLETED" => (HttpStatusCode.ServiceUnavailable, ToJson(processingResult)),
                    _ => (HttpStatusCode.InternalServerError, ToJson(processingResult))
                };
            }
            catch (JsonException)
            {
                return (HttpStatusCode.BadRequest, ToJson(new { Error = "Invalid JSON structure parsed." }));
            }
            catch (Exception ex)
            {
                return (HttpStatusCode.InternalServerError, ToJson(new { Error = $"Critical System Exception: {ex.Message}" }));
            }
        }

        private static string ToJson(object obj) => JsonSerializer.Serialize(obj, new JsonSerializerOptions { WriteIndented = true });
    }

    #endregion

    #region EXECUTION HARNESS & CONCURRENCY SIMULATOR

    public static class Program
    {
        public static async Task Main()
        {
            Console.WriteLine("==========================================================");
            Console.WriteLine("STARTING ENTERPRISE ORDER AND INVENTORY PIPELINE DEMO");
            Console.WriteLine("==========================================================\n");

            // Setup Services
            var inventoryEngine = new InventoryReservationEngine();
            var circuitBreaker = new CustomCircuitBreaker(failureThreshold: 2, breakDuration: TimeSpan.FromSeconds(3));
            var paymentService = new PaymentGatewayService(circuitBreaker);
            var coordinator = new OrderProcessingCoordinator(inventoryEngine, paymentService);
            var controller = new OrdersApiController(coordinator);

            #region SCENARIO 1: HIGH CONCURRENCY RACE CONDITION SIMULATION

            Console.WriteLine("----------------------------------------------------------");
            Console.WriteLine("SCENARIO 1: High Concurrency Lock Execution");
            Console.WriteLine("Firing 5 concurrent requests attempting to purchase SKU-MONITOR (Stock limit: 2)");
            Console.WriteLine("----------------------------------------------------------");

            string requestPayload = @"
            {
                ""CustomerId"": ""CUST-8812"",
                ""Items"": [
                    { ""ProductId"": ""PROD-003"", ""Quantity"": 1 }
                ]
            }";

            var tasks = new List<Task<(HttpStatusCode StatusCode, string JsonResponse)>>();
            for (int i = 0; i < 5; i++)
            {
                tasks.Add(Task.Run(() => controller.PostOrderAsync(requestPayload)));
            }

            var results = await Task.WhenAll(tasks);
            int successfulReservations = results.Count(r => r.StatusCode == HttpStatusCode.Created);
            int rejectedReservations = results.Count(r => r.StatusCode == HttpStatusCode.Conflict);

            Console.WriteLine($"\n[CONCURRENCY SUMMARY] Completed processes. Successful: {successfulReservations}, Rejected: {rejectedReservations}");

            #endregion

            #region SCENARIO 2: GATEWAY FAILURES AND CIRCUIT BREAKER TRIP

            Console.WriteLine("\n----------------------------------------------------------");
            Console.WriteLine("SCENARIO 2: Transient Failures & Circuit Breaker Triggers");
            Console.WriteLine("Sending high-value orders (> $5,000) to deliberately trip the payment gateway");
            Console.WriteLine("----------------------------------------------------------");

            // PROD-001 costs $999.99. Ordering 6 of them exceeds $5,000, triggering gateway failures.
            string expensivePayload = @"
            {
                ""CustomerId"": ""CUST-9999"",
                ""Items"": [
                    { ""ProductId"": ""PROD-001"", ""Quantity"": 6 }
                ]
            }";

            // Request 1: Triggers first payment failure (Circuit State: CLOSED -> Failure count = 1)
            var response1 = await controller.PostOrderAsync(expensivePayload);
            Console.WriteLine($"Request 1 Result Status: {response1.StatusCode}\n");

            // Request 2: Triggers second payment failure (Threshold met: State trips to OPEN)
            var response2 = await controller.PostOrderAsync(expensivePayload);
            Console.WriteLine($"Request 2 Result Status: {response2.StatusCode}\n");

            // Request 3: Fast-Fails instantly because the Circuit is OPEN (no lock allocations, no gateway calls made)
            Console.WriteLine("[CLIENT ACTION] Dispatching 3rd Request while circuit is OPEN...");
            var response3 = await controller.PostOrderAsync(expensivePayload);
            Console.WriteLine($"Request 3 Result Status: {response3.StatusCode}");
            Console.WriteLine($"Payload response:\n{response3.JsonResponse}\n");

            #endregion

            #region SCENARIO 3: CIRCUIT RECOVERY AND STATE CONVERSION

            Console.WriteLine("----------------------------------------------------------");
            Console.WriteLine("SCENARIO 3: Cooldown and Auto-Recovery Probe Verification");
            Console.WriteLine("Waiting for circuit break duration to expire (3 seconds)...");
            Console.WriteLine("----------------------------------------------------------");

            await Task.Delay(3500); // Wait for open window to decay

            // Attempt to place a valid, low-value purchase (Circuit is in Half-Open probe state)
            string cheapPayload = @"
            {
                ""CustomerId"": ""CUST-0001"",
                ""Items"": [
                    { ""ProductId"": ""PROD-002"", ""Quantity"": 1 }
                ]
            }";

            Console.WriteLine("[CLIENT ACTION] Dispatching probe request for low-cost product under Half-Open state...");
            var probeResponse = await controller.PostOrderAsync(cheapPayload);
            Console.WriteLine($"Probe Request Result Status: {probeResponse.StatusCode}");
            Console.WriteLine($"Response Data: \n{probeResponse.JsonResponse}");

            #endregion

            Console.WriteLine("\n==========================================================");
            Console.WriteLine("DEMO COMPLETED SUCCESSFULLY WITH INTEGRITY MAINTAINED");
            Console.WriteLine("==========================================================");
        }
    }

    #endregion
}
```

